"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar, MapPin, Globe, Sparkles, Flag, 
  ChevronDown, Search, LayoutGrid, ListFilter 
} from "lucide-react";

/* --- 1. DATASET --- */
const HOLIDAYS_DB = [
  // 2025
  { id: 1, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Wed", year: "2025", type: "Public", country: "Global", region: "All" },
  { id: 2, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Sun", year: "2025", type: "National", country: "India", region: "All" },
  { id: 3, name: "Presidents' Day", date: "Feb 17", monthIdx: 1, day: "Mon", year: "2025", type: "Public", country: "USA", region: "All" },
  { id: 4, name: "Holi", date: "Mar 14", monthIdx: 2, day: "Fri", year: "2025", type: "Optional", country: "India", region: "North India" },
  { id: 5, name: "Good Friday", date: "Apr 18", monthIdx: 3, day: "Fri", year: "2025", type: "Public", country: "Global", region: "All" },
  
  // 2026
  { id: 6, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Thu", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 7, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Mon", year: "2026", type: "National", country: "India", region: "All" },
  { id: 8, name: "Ugadi", date: "Mar 19", monthIdx: 2, day: "Thu", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  { id: 9, name: "Memorial Day", date: "May 25", monthIdx: 4, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  { id: 10, name: "Kannada Rajyotsava", date: "Nov 01", monthIdx: 10, day: "Sun", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 11, name: "Christmas", date: "Dec 25", monthIdx: 11, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
];

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const REGIONS_BY_COUNTRY: any = {
    "All": ["All", "Telangana", "Karnataka", "North India", "New York"],
    "India": ["All", "Telangana", "Karnataka", "North India"],
    "USA": ["All", "New York", "California"],
    "Global": ["All"]
};

export default function UserFriendlyHolidayHub() {
  const [year, setYear] = useState("2026");
  const [country, setCountry] = useState("All");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  /* --- LOGIC ENGINE --- */
  const groupedHolidays = useMemo(() => {
    const filtered = HOLIDAYS_DB.filter((h) => {
      const matchYear = h.year === year;
      const matchCountry = country === "All" || h.country === country || h.country === "Global";
      const matchRegion = region === "All" || h.region === region || h.region === "All";
      const matchType = type === "All" || h.type === type;
      return matchYear && matchCountry && matchRegion && matchType;
    });

    filtered.sort((a, b) => a.monthIdx - b.monthIdx);

    const groups: Record<string, typeof filtered> = {};
    filtered.forEach(h => {
        const monthKey = MONTH_NAMES[h.monthIdx];
        if (!groups[monthKey]) groups[monthKey] = [];
        groups[monthKey].push(h);
    });

    return groups;
  }, [year, country, region, type]);

  return (
    <div className="min-h-screen bg-[#F9FAFB] dark:bg-[#09090b] text-slate-900 dark:text-slate-100 font-sans">
      
      {/* --- 1. COMPACT NAV HEADER --- */}
      <div className="bg-white dark:bg-[#121212] border-b border-slate-200 dark:border-slate-800 px-6 py-4 sticky top-0 z-50">
         <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
            
            {/* Title Block */}
            <div className="flex items-center gap-3 w-full md:w-auto">
               <div className="p-2 bg-brand-50 dark:bg-brand-500/10 rounded-lg text-brand-600">
                  <Calendar size={20} />
               </div>
               <div>
                  <h1 className="text-lg font-bold text-slate-900 dark:text-white leading-tight">Holiday Calendar</h1>
                  <p className="text-xs text-slate-500 font-medium">Official Schedule • {year}</p>
               </div>
            </div>

            {/* Filter Cockpit */}
            <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
                <CompactDropdown 
                   icon={<Flag size={14} />}
                   value={country} 
                   onChange={(v: string) => { setCountry(v); setRegion('All'); }} 
                   options={['All', 'India', 'USA']} 
                />
                <CompactDropdown 
                   icon={<MapPin size={14} />}
                   value={region} 
                   onChange={setRegion} 
                   options={REGIONS_BY_COUNTRY[country] || ['All']} 
                   disabled={country === 'Global'}
                />
                <div className="h-8 w-[1px] bg-slate-200 dark:bg-slate-700 mx-1 hidden md:block" />
                <YearToggle value={year} onChange={setYear} />
            </div>
         </div>
      </div>

      {/* --- 2. SUB-HEADER: TYPE FILTER --- */}
      <div className="bg-white/50 dark:bg-[#09090b]/50 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-6 py-2">
         <div className="max-w-7xl mx-auto flex items-center gap-2 overflow-x-auto no-scrollbar">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mr-2 flex-shrink-0">
               <ListFilter size={12} className="inline mr-1" /> View:
            </span>
            {['All', 'Public', 'Optional'].map(t => (
               <button 
                  key={t} 
                  onClick={() => setType(t)} 
                  className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-all flex-shrink-0 ${
                     type === t 
                     ? "bg-slate-900 text-white dark:bg-white dark:text-black shadow-sm" 
                     : "text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800"
                  }`}
               >
                  {t}
               </button>
            ))}
         </div>
      </div>

      {/* --- 3. MAIN CONTENT GRID --- */}
      <div className="max-w-7xl mx-auto px-6 py-10 space-y-12">
         {Object.keys(groupedHolidays).length > 0 ? (
            Object.keys(groupedHolidays).map((month) => (
               <div key={month} className="flex flex-col md:flex-row gap-6 md:gap-12">
                  
                  {/* Sticky Month Label */}
                  <div className="md:w-32 flex-shrink-0">
                     <div className="sticky top-32">
                        <h2 className="text-lg font-bold text-slate-900 dark:text-white">{month}</h2>
                        <span className="text-xs font-medium text-slate-400">{groupedHolidays[month].length} Events</span>
                     </div>
                  </div>

                  {/* Cards Grid */}
                  <div className="flex-1 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                     {groupedHolidays[month].map((h) => (
                        <CleanCard key={h.id} data={h} />
                     ))}
                  </div>
               </div>
            ))
         ) : (
            <div className="py-20 text-center bg-white dark:bg-[#121212] rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">
               <div className="mx-auto w-12 h-12 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center text-slate-400 mb-3">
                  <Search size={20} />
               </div>
               <p className="text-sm font-medium text-slate-500">No holidays match your filters.</p>
               <button onClick={() => {setCountry('All'); setType('All')}} className="mt-2 text-xs font-bold text-brand-600 hover:underline">Clear Filters</button>
            </div>
         )}
      </div>

    </div>
  );
}

/* --- COMPONENTS --- */

const CleanCard = ({ data }: { data: any }) => (
   <div className="bg-white dark:bg-[#121212] border border-slate-200 dark:border-slate-800 rounded-xl p-4 hover:shadow-md hover:border-brand-500/30 transition-all group">
      <div className="flex gap-4 items-center">
         {/* Date Box */}
         <div className="flex-shrink-0 w-14 h-14 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-100 dark:border-slate-700 flex flex-col items-center justify-center group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
            <span className="text-[10px] font-bold text-slate-400 uppercase">{data.day}</span>
            <span className="text-lg font-bold text-slate-900 dark:text-white leading-none">{data.date.split(' ')[1]}</span>
         </div>
         
         {/* Content */}
         <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2 mb-1">
               <span className={`w-1.5 h-1.5 rounded-full ${data.type === 'Optional' ? 'bg-amber-500' : 'bg-emerald-500'}`} />
               <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wide truncate">
                  {data.type} • {data.country === 'Global' ? 'Global' : data.region}
               </span>
            </div>
            <h3 className="text-sm font-bold text-slate-900 dark:text-white truncate" title={data.name}>
               {data.name}
            </h3>
         </div>
      </div>
   </div>
);

const CompactDropdown = ({ icon, value, onChange, options, disabled }: any) => (
   <div className={`relative h-9 min-w-[140px] flex-1 md:flex-none ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
      <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">{icon}</div>
      <select 
         value={value} 
         onChange={(e) => onChange(e.target.value)} 
         disabled={disabled}
         className="w-full h-full bg-slate-100 dark:bg-slate-800 rounded-lg pl-9 pr-8 text-xs font-semibold text-slate-700 dark:text-slate-200 appearance-none outline-none focus:ring-2 focus:ring-brand-500/20 cursor-pointer border border-transparent hover:border-slate-300 dark:hover:border-slate-600 transition-colors"
      >
         {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
      </select>
      <ChevronDown size={14} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
   </div>
);

const YearToggle = ({ value, onChange }: any) => (
   <div className="bg-slate-100 dark:bg-slate-800 rounded-lg p-1 flex h-9">
      {['2025', '2026'].map(y => (
         <button 
            key={y} 
            onClick={() => onChange(y)}
            className={`px-3 text-xs font-bold rounded-md transition-all ${
               value === y 
               ? "bg-white dark:bg-slate-600 text-slate-900 dark:text-white shadow-sm" 
               : "text-slate-500 hover:text-slate-700"
            }`}
         >
            {y}
         </button>
      ))}
   </div>
);